export async function seedAhlReference(db: any) {
  // 1. species groups (upsert by code)
  for (const sg of AHL_SPECIES_GROUPS) {
    await db.insert(speciesGroups).values(sg).onConflictDoUpdate({ target: speciesGroups.code, set: sg });
  }
  const allSg = await db.select().from(speciesGroups);
  const sgId = new Map(allSg.map((s: any) => [s.code, s.id]));
  // 2. diseases (upsert by name)
  for (const d of AHL_LISTED_DISEASES) {
    await db.insert(diseases).values(d).onConflictDoUpdate({ target: diseases.name, set: d });
  }
  const allD = await db.select().from(diseases);
  const dId = new Map(allD.map((d: any) => [d.name, d.id]));
  // 3. applicability (upsert by disease+species+role)
  for (const a of AHL_DISEASE_SPECIES) {
    const row = { diseaseId: dId.get(a.diseaseName), speciesGroupId: sgId.get(a.speciesGroupCode), role: a.role === 'HOST' ? APPLICABILITY_ROLE.HOST : APPLICABILITY_ROLE.VECTOR, categories: a.categories } as const;
    await db.insert(diseaseSpeciesApplicability).values(row).onConflictDoUpdate({ target: [diseaseSpeciesApplicability.diseaseId, diseaseSpeciesApplicability.speciesGroupId, diseaseSpeciesApplicability.role], set: row });
  }
  console.log(`  ✓ AHL reference: ${AHL_LISTED_DISEASES.length} diseases, ${AHL_SPECIES_GROUPS.length} species groups, ${AHL_DISEASE_SPECIES.length} applicability rows`);
}
